CREATE COLUMN TABLE "TEST_AP"."OWDD" ("WddCode" INTEGER CS_INT NOT NULL , "WtmCode" INTEGER CS_INT, "OwnerID" INTEGER CS_INT, "DocEntry" INTEGER CS_INT, "ObjType" NVARCHAR(20), "DocDate" LONGDATE CS_LONGDATE, "CurrStep" INTEGER CS_INT, "Status" NVARCHAR(1) DEFAULT 'W', "Remarks" NVARCHAR(254), "UserSign" SMALLINT CS_INT, "CreateDate" LONGDATE CS_LONGDATE, "CreateTime" SMALLINT CS_INT, "IsDraft" NVARCHAR(1) DEFAULT 'Y', "MaxReqr" SMALLINT CS_INT, "MaxRejReqr" SMALLINT CS_INT, "SrcDocEnt" INTEGER CS_INT, "DraftType" NVARCHAR(20), "DraftEntry" INTEGER CS_INT, "BFType" NVARCHAR(1), "ProcessID" INTEGER CS_INT, "ProcesStat" NVARCHAR(1) DEFAULT 'W', "StpUpdated" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("WddCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "OWDD_PROCESS" ON "TEST_AP"."OWDD" ( "ProcessID" ASC )